#include "gfx.h"
#include "font.h"

void splash_draw(uint8_t *fb)
{
	static const char v[] = "PicoWikiGuide " PWG_VERSION;
	memset(fb, 0, SCREEN_STRIDE * SCREEN_H);
	gfx_fill(fb, SCREEN_STRIDE, SCREEN_H, 0, 0, SCREEN_W, SCREEN_H, BLACK);
	gfx_blit2(fb, SCREEN_STRIDE, SCREEN_H, (SCREEN_W - splash_w) / 2,
		  (SCREEN_H - 24 - splash_h) / 2, splash_bits, splash_w, splash_h, WHITE);
	font_draw(fb, SCREEN_STRIDE, SCREEN_H,
		  (SCREEN_W - font_width(FONT_SMALLL, v, sizeof(v) - 1)) / 2, SCREEN_H - 12,
		  FONT_SMALLL, v, sizeof(v) - 1, WHITE);
}
